(()=>{'use strict';
const root=document.documentElement;
const menu=document.querySelector('[data-menu-toggle]'),nav=document.querySelector('[data-navigation]');
if(menu&&nav){menu.hidden=false;root.classList.add('js');const setMenu=(open)=>{menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Закрыть меню':'Открыть меню');nav.classList.toggle('is-open',open);};menu.addEventListener('click',()=>setMenu(menu.getAttribute('aria-expanded')!=='true'));nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>setMenu(false)));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){setMenu(false);menu.focus();}});document.addEventListener('click',e=>{if(!e.target.closest('.site-header'))setMenu(false);});matchMedia('(min-width:761px)').addEventListener('change',()=>setMenu(false));}
const themeButton=document.querySelector('[data-theme-toggle]');
function applyTheme(theme){root.dataset.theme=theme;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',theme==='dark'?'#10131c':'#f7f5ef');if(themeButton){themeButton.setAttribute('aria-label',theme==='dark'?'Включить светлую тему':'Включить тёмную тему');themeButton.setAttribute('aria-pressed',String(theme==='dark'));}}
if(themeButton){themeButton.hidden=false;applyTheme(root.dataset.theme||'light');themeButton.addEventListener('click',()=>{const theme=root.dataset.theme==='dark'?'light':'dark';applyTheme(theme);try{localStorage.setItem('akaalexey-theme',theme);}catch{}});matchMedia('(prefers-color-scheme:dark)').addEventListener('change',e=>{let saved;try{saved=localStorage.getItem('akaalexey-theme');}catch{}if(!saved)applyTheme(e.matches?'dark':'light');});}
const reduced=matchMedia('(prefers-reduced-motion:reduce)');
if('IntersectionObserver'in window&&!reduced.matches){root.classList.add('motion-ready');const io=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.remove('reveal-pending');io.unobserve(e.target);}});},{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>{if(el.getBoundingClientRect().top>innerHeight){el.classList.add('reveal-pending');io.observe(el);}});reduced.addEventListener('change',e=>{if(e.matches){document.querySelectorAll('.reveal-pending').forEach(el=>el.classList.remove('reveal-pending'));io.disconnect();}});}
document.querySelectorAll('[data-copy-contact]').forEach(b=>b.addEventListener('click',async()=>{const status=document.querySelector('[data-copy-status]');try{await navigator.clipboard.writeText('@akaAlexey');if(status)status.textContent='Ник скопирован';}catch{if(status)status.textContent='Telegram: @akaAlexey';}}));
const dialog=document.querySelector('[data-image-dialog]');if(dialog&&typeof dialog.showModal==='function'){let opener;document.querySelectorAll('[data-preview-image]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();opener=a;dialog.querySelector('img').src=a.href;dialog.querySelector('img').alt=a.dataset.imageAlt||'';dialog.querySelector('[data-image-caption]').textContent=a.dataset.imageAlt||'Иллюстрация';dialog.showModal();}));dialog.querySelector('button').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>opener?.focus());}
document.querySelectorAll('[data-year]').forEach(el=>el.textContent=String(new Date().getFullYear()));
})();
